python3 -c 'import pathlib,json
P=pathlib.Path
def read(p):
 try:return p.read_text()
 except OSError as e:return {"unavailable":str(e)}
names=["qcom_glink_cmd_version","qcom_glink_cmd_version_ack","qcom_glink_cmd_open","qcom_glink_cmd_open_ack","qcom_glink_cmd_close","qcom_glink_cmd_close_ack"]
roots=[P("/sys/kernel/tracing"),P("/sys/kernel/debug/tracing")]
result={"boot_id":read(P("/proc/sys/kernel/random/boot_id")),"device_operations":False,"trace_roots":{}}
for root in roots:
 if not root.exists():continue
 result["trace_roots"][str(root)]={"resolved":str(root.resolve()),"tracing_on":read(root/"tracing_on"),"current_tracer":read(root/"current_tracer"),"events":{name:{"format":read(root/"events/qcom_glink"/name/"format"),"enabled":read(root/"events/qcom_glink"/name/"enable")} for name in names},"instances":[p.name for p in (root/"instances").glob("*")]}
print(json.dumps(result,indent=2))'
